<template><div class="page-shell"><aside class="sidebar"><div class="brand">☰　工业互联网平台</div><div class="nav-title">安全基础信息</div><div class="nav-item">人员管理</div><div class="nav-item">企业安全基础</div><div class="nav-item active">●　资质证书管理</div><div class="nav-item">安全厂房管理</div><div class="nav-item">车间安全运行</div><div class="nav-item">设备设施管理　⌄</div><div class="nav-item">隐患排查治理　⌄</div></aside><main class="main"><div class="topbar"><span class="crumb">瑞木博士</span><span class="crumb current">● 资质证书管理 ×</span></div><div class="content"><div class="detail-head"><el-page-header content="三同时信息" @back="back" /><el-tag v-if="mode==='view'" type="info">查看</el-tag><el-tag v-else type="warning">编辑</el-tag></div><el-card shadow="never" class="detail-card"><el-form ref="form" :model="form" :rules="rules" label-width="130px" :disabled="mode==='view'"><div class="section-title">项目基本信息</div><el-row :gutter="30"><el-col :span="12"><el-form-item label="项目名称" prop="project"><el-input v-model="form.project" placeholder="请输入项目名称" /></el-form-item></el-col><el-col :span="12"><el-form-item label="项目负责人"><el-input v-model="form.owner" placeholder="请输入负责人" /></el-form-item></el-col></el-row><div class="section-title">环评审批信息</div><el-row :gutter="30"><el-col :span="12"><el-form-item label="环评文件类型"><el-select v-model="form.fileType"><el-option label="报告书" value="报告书" /><el-option label="报告表" value="报告表" /><el-option label="登记表" value="登记表" /></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="审批单位"><el-input v-model="form.approvalUnit" /></el-form-item></el-col><el-col :span="12"><el-form-item label="批准时间"><el-date-picker v-model="form.approvalDate" type="date" value-format="yyyy-MM-dd" /></el-form-item></el-col><el-col :span="12"><el-form-item label="批准文号"><el-input v-model="form.approvalNo" /></el-form-item></el-col></el-row><div class="section-title">验收与许可证</div><el-row :gutter="30"><el-col :span="12"><el-form-item label="验收状态"><el-select v-model="form.acceptanceStatus"><el-option label="未验收" value="未验收" /><el-option label="已验收" value="已验收" /></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="验收时间"><el-date-picker v-model="form.acceptanceDate" type="date" value-format="yyyy-MM-dd" /></el-form-item></el-col><el-col :span="24"><el-form-item label="附件资料"><el-upload action="#" :auto-upload="false" :disabled="mode==='view'" :on-change="fileChanged"><el-button icon="el-icon-upload2">上传附件</el-button></el-upload><span class="muted">当前为 Mock 上传，不提交后台</span></el-form-item></el-col></el-row></el-form><div class="footer-actions"><el-button @click="back">返回列表</el-button><el-button v-if="mode!=='view'" type="primary" @click="save">保存{{ mode==='create' ? '项目' : '修改' }}</el-button></div></el-card></div></main></div></template>
<script>
import { projects } from '../mock/threeSame'
export default { name: 'ThreeSameDetail', props: { id: [String, Number], type: String }, data () { const mode = this.$route.query.mode || 'view'; const source = projects.find(x => String(x.id) === String(this.id)); return { mode, form: Object.assign({ project: '', owner: '', fileType: '报告书', approvalUnit: '', approvalDate: '', approvalNo: '', acceptanceStatus: '未验收', acceptanceDate: '' }, source || {}), rules: { project: [{ required: true, message: '请输入项目名称', trigger: 'blur' }] } } }, methods: { back () { this.$router.push({ name: 'three-same-list', params: { type: this.type || 'environment' } }) }, fileChanged () {}, save () { this.$refs.form.validate(valid => { if (!valid) return; if (this.id === 'new') projects.push(Object.assign({ id: Date.now(), type: this.type || 'environment', status: '资料不完整' }, this.form)); else { const target = projects.find(x => String(x.id) === String(this.id)); if (target) Object.assign(target, this.form) } this.$message.success('已保存到本地 Mock 数据'); this.back() }) } } }
</script>
